import math

def radian_degree():
    # 1 度等于 π / 180 弧度
    # 我们可以使用数学公式：弧度 = 度数 × π / 180 来实现度数与弧度之间的转换
    # 我们需要一个函数来计算度数与弧度之间的转换率
    def degree_to_radian(degree):
        # 使用数学公式计算弧度
        radian = degree * math.pi / 180
        return radian

    # 我们需要一个函数来计算弧度与度数之间的转换率
    def radian_to_degree(radian):
        # 使用数学公式计算度数
        degree = radian * 180 / math.pi
        return degree

    # 我们需要一个函数来实现度数与弧度之间的转换
    def convert(degree_or_radian):
        # 如果输入的是度数，则转换为弧度
        if isinstance(degree_or_radian, (int, float)):
            return degree_to_radian(degree_or_radian)
        # 如果输入的是弧度，则转换为度数
        elif isinstance(degree_or_radian, (int, float)) and math.isclose(degree_or_radian, 0, abs_tol=1e-9):
            return radian_to_degree(degree_or_radian)
        else:
            raise ValueError("输入类型错误")

    # 我们需要一个函数来实现度数与弧度之间的转换
    def convert_degree_to_radian(degree):
        return convert(degree)

    # 我们需要一个函数来实现度数与弧度之间的转换
    def convert_radian_to_degree(radian):
        return convert(radian)

    # 我们需要一个函数来实现度数与弧度之间的转换
    def convert_degree(degree):
        return convert(degree)

